import json, sys

def truncate(s, n=300):
    s = str(s)
    if len(s) > n:
        return s[:n] + f"...[{len(s)}chars]"
    return s

def main(path):
    prev_ts = None
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                d = json.loads(line)
            except Exception:
                continue
            t = d.get('type')
            ts = d.get('timestamp')
            gap = ''
            if ts and prev_ts:
                try:
                    from datetime import datetime
                    fmt = "%Y-%m-%dT%H:%M:%S.%fZ"
                    t1 = datetime.strptime(prev_ts, fmt)
                    t2 = datetime.strptime(ts, fmt)
                    dt = (t2 - t1).total_seconds()
                    if dt > 15:
                        gap = f"  [GAP {dt:.1f}s]"
                except Exception:
                    pass
            if ts:
                prev_ts = ts

            if t == 'assistant':
                msg = d.get('message', {})
                content = msg.get('content', [])
                if isinstance(content, str):
                    print(f"{ts} ASSISTANT-TEXT: {truncate(content,200)}{gap}")
                else:
                    for block in content:
                        bt = block.get('type')
                        if bt == 'text':
                            txt = block.get('text','').strip()
                            if txt:
                                print(f"{ts} ASSISTANT-TEXT: {truncate(txt,250)}{gap}")
                        elif bt == 'tool_use':
                            name = block.get('name')
                            inp = block.get('input', {})
                            print(f"{ts} TOOL_USE {name}: {truncate(json.dumps(inp), 200)}{gap}")
            elif t == 'user':
                msg = d.get('message', {})
                content = msg.get('content', [])
                is_meta = d.get('isMeta')
                if isinstance(content, str):
                    if content.strip():
                        print(f"{ts} USER-TEXT{'(meta)' if is_meta else ''}: {truncate(content,250)}{gap}")
                else:
                    for block in content:
                        bt = block.get('type')
                        if bt == 'text':
                            txt = block.get('text','').strip()
                            if txt:
                                print(f"{ts} USER-TEXT{'(meta)' if is_meta else ''}: {truncate(txt,250)}{gap}")
                        elif bt == 'tool_result':
                            c = block.get('content')
                            is_err = block.get('is_error')
                            if isinstance(c, list):
                                c = ' '.join(x.get('text','') for x in c if isinstance(x, dict))
                            print(f"{ts} TOOL_RESULT{' ERROR' if is_err else ''}: {truncate(c,250)}{gap}")
            elif t == 'attachment':
                att = d.get('attachment', {})
                name = att.get('hookName') or att.get('type')
                # skip most attachments (system reminders) unless they carry content worth noting
            # skip queue-operation, ai-title, atis-latch, last-prompt

if __name__ == '__main__':
    main(sys.argv[1])

