content.content:
160	}
161	
162	// The grammar faults of one entry on its own, before the file it would join is read.
163	export function entryProblems(entry, { kinds = KINDS } = {}) {
164	  const problems = [];
165	  if (!kinds.includes(entry.kind)) problems.push(`kind "${entry.kind}" is not in the vocabulary (${kinds.join(', ')})`);
166	  if (!/^\d{4}-\d{2}-\d{2}$/.test(entry.date ?? '') || Number.isNaN(Date.parse(`${entry.date}T00:00:00Z`))) problems.push(`date "${entry.date}" is not a YYYY-MM-DD date`);
167	  if (!entry.title || !String(entry.title).trim()) problems.push('an entry needs its one-line title');
168	  for (const name of Object.keys(entry.fields ?? {})) if (!FIELDS.includes(name)) problems.push(`field "${name}" is not in the vocabulary`);
169	  if (MECHANISM_KINDS.includes(entry.kind) && !String(entry.fields?.Mechanism ?? '').trim()) problems.push(`a ${entry.kind} entry carries Mechanism: the carrier and its trigger, and why`);
170	  return problems;
171	}
172	
173	// Validate an entry against the grammar and the file it would join, then return the
174	// text to write back. Refuses rather than writes: the caller decides what a refusal
175	// costs. `firstKind` is what an empty file's first entry must be (null: anything).
176	// This is the ordinary lane, and it is append-only: an entry dated before the file's
177	// last one is refused, because a change being recorded now cannot have happened before
178	// the change recorded last. The backfill is the one lane that writes the past, and it
179	// goes through `backfilledText` instead.
180	export function appendedText(existing, entry, { kinds = KINDS, firstKind = 'born' } = {}) {
181	  const problems = entryProblems(entry, { kinds });
182	  const { entries, errors } = parseEntries(existing, { kinds });
183	  if (errors.length) problems.push(`the file does not parse (line ${errors[0].line}: ${errors[0].what})`);
184	  const last = entries[entries.length - 1];
185	  if (last && entry.date < last.date) problems.push(`the file's last entry is dated ${last.date}; an entry is appended in date order`);
186	  if (last && last.kind === 'retired') problems.push('the element is retired; a retired file is appended to by nothing');
187	  if (!entries.length && firstKind && entry.kind !== firstKind) problems.push(`the first entry of a file is ${firstKind}, not ${entry.kind}`);
188	  if (problems.length) return { problems };
189	  const body = renderEntry(entry);
190	  const text = String(existing ?? '');
191	  if (text.trim() === '') return { problems: [], text: body };
192	  const glue = text.endsWith('\n\n') ? '' : text.endsWith('\n') ? '\n' : '\n\n';
193	  return { problems: [], text: `${text}${glue}${body}` };
194	}
195	
196	// One parsed entry as `renderEntry` takes it, its fields in the file's own order.
197	const asEntry = (e) => ({ date: e.date, kind: e.kind, title: e.title, fields: Object.fromEntries(e.order.map((n) => [n, e.fields[n]])) });
198	const headingOf = (e) => `${e.date} · ${e.kind} · ${e.title}`;
199	
200	// The backfill's write, and the ONE place a provenance file is rewritten rather than
201	// appended to. A backfill derives an element's whole history at once from commits that
202	// are already in the past, so its entries are dated before whatever the file holds -
203	// which the append lane refuses, correctly, for every other caller. Here the file is
204	// re-rendered from its existing entries and the batch merged in date order.
205	//
206	// A file the references conversion filled carries a placeholder `born` dated by the
207	// conversion write rather than by the element's birth. Where the batch supplies a born
208	// dated EARLIER, that placeholder is the thing being corrected, so it is dropped and
209	// named in `superseded`; where the placeholder's date is the real birth, no earlier
210	// born arrives and it stands. That distinction is read off the dates rather than left
211	// to the run, which is why this is the tool's job and not a prompt's (#2223).
212	export function backfilledText(existing, entries, { kinds = KINDS, firstKind = 'born' } = {}) {
213	  const problems = [];
214	  for (const e of entries) problems.push(...entryProblems(e, { kinds }));
215	  const { entries: held, errors } = parseEntries(existing, { kinds });
216	  if (errors.length) problems.push(`the file does not parse (line ${errors[0].line}: ${errors[0].what})`);
217	  if (problems.length) return { problems, superseded: [] };
218	  const born = entries.filter((e) => e.kind === 'born').map((e) => e.date).sort()[0];
219	  const superseded = [];
220	  const keep = held.map(asEntry).filter((e) => {
221	    // Only the conversion's own placeholder is replaced, never an entry somebody wrote:
222	    // a batch carrying an earlier born would otherwise silently delete real history, and
223	    // the point of this lane is to correct a date the conversion never knew.
224	    if (born && e.kind === 'born' && e.date > born && CONVERTED_TITLE.test(e.title ?? '')) { superseded.push(headingOf(e)); return false; }
225	    return true;
226	  });
227	  const merged = [...keep];
228	  for (const e of entries) if (!merged.some((m) => headingOf(m) === headingOf(e))) merged.push(e);
229	  // A stable sort by date alone: entries of one day keep the order they arrived in,
230	  // the file's own first and then the batch's, which is the order a run wrote them.
231	  const ordered = merged.map((e, i) => ({ e, i })).sort((a, b) => a.e.date.localeCompare(b.e.date) || a.i - b.i).map(({ e }) => e);
232	  if (ordered.length && firstKind && ordered[0].kind !== firstKind) problems.push(`the file would open with ${ordered[0].kind}; the first entry of a file is ${firstKind}`);
233	  const retiredAt = ordered.findIndex((e) => e.kind === 'retired');
234	  if (retiredAt !== -1 && retiredAt !== ordered.length - 1) problems.push(`a retired entry is a file's last; "${headingOf(ordered[retiredAt])}" would sit above ${ordered.length - 1 - retiredAt} more`);
235	  if (ordered.filter((e) => e.kind === 'born').length > 1) problems.push('the batch would leave two born entries in one file; an element is born once');
236	  if (problems.length) return { problems, superseded };
237	  return { problems: [], superseded, text: ordered.map((e) => renderEntry(e)).join('\n') };
238	}
239	
240	// Parse an entry written in the file grammar (what `append` reads from stdin).
241	export function parseEntryText(text) {
242	  const { entries, errors } = parseEntries(text, { kinds: [...KINDS, DECLINED_KIND] });
243	  if (entries.length !== 1) return { problems: [`expected exactly one entry, found ${entries.length}`] };
244	  if (errors.length) return { problems: errors.map((e) => `line ${e.line}: ${e.what}`) };
